var i=`1214-baho`;var n=`world-1214`;var r=`NI`;var t=`central-america-caribbean`;var o=8;var s=258;var l={en:`Baho`,ua:`Бахо`};var g={en:`Baho is a dish from Nicaragua featuring beef brisket, orange juice, garlic, banana leaf. This home-sized recipe records each ingredient at the step where it is used. A steamer and food-safe banana leaves approximate traditional large wrapped baho; verify beef is fully cooked.`,ua:`Бахо, страва кухні країни Нікарагуа з такими основними складниками: яловича грудинка, апельсиновий сік, часник, банановий лист. У домашньому рецепті кожний продукт прив’язаний до етапу його використання. Пароварка і харчове бананове листя наближають традиційний великий пакунок бахо; перевіряйте готовність яловичини.`};var d=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 90 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 90 хвилин.`,t:[`marinating`],m:90,i:[[`beef-brisket`,800,`g`],[`orange-juice`,130,`ml`],[`garlic`,5,`clove`],[`ground-cumin`,5,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:14,i:[[`banana-leaf`,8,`leaf`],[`plantain`,720,`g`],[`cassava-root`,550,`g`]]},{en:`Steam the already prepared parcels or mixture over gently boiling water for approximately 150 minutes, until fully cooked or set.`,ua:`Готуйте раніше підготовлені згортки або масу на парі над слабким кипінням близько 150 хвилин до готовності.`,t:[`steaming`],m:150,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`red-onion`,130,`g`],[`tomato`,250,`g`]]}];var c={slug:i,id:n,country:`NI`,region:t,servings:8,minutes:258,title:l,text:g,steps:d};export{r as country,c as default,n as id,s as minutes,t as region,o as servings,i as slug,d as steps,g as text,l as title};